head.b:template-skin:
/* 「레이아웃」 편집 화면 전용 — 모든 영역·가젯을 같은 너비(640px)로 가운데 정렬 (실제 사이트에는 영향 없음) */
body#layout { overflow: visible !important; background: #f1f5f9 !important; min-height: 100vh !important; padding: 24px 0 60px !important; margin: 0 !important; font: normal normal 13px Pretendard, 'Noto Sans KR', sans-serif !important; }
body#layout .dl-skip, body#layout #dlMenu { display: none !important; }
body#layout #outer-wrapper, body#layout #dl-main, body#layout .ad-warehouse, body#layout .ad-warehouse-nav {
  display: block !important; position: static !important; float: none !important; box-sizing: border-box !important;
  width: 640px !important; max-width: calc(100% - 24px) !important; margin: 0 auto !important; padding: 0 !important; border: 0 !important; background: none !important; overflow: visible !important; height: auto !important; }
body#layout #dl-main, body#layout #outer-wrapper #dl-main { width: 100% !important; max-width: 100% !important; }
body#layout div.section, body#layout .section {
  display: block !important; position: relative !important; float: none !important; clear: both !important; box-sizing: border-box !important;
  width: 640px !important; max-width: calc(100% - 24px) !important; min-width: 0 !important; height: auto !important; min-height: 60px !important;
  margin: 0 auto 14px !important; padding: 12px !important;
  border: 1px dashed #cbd5e1 !important; border-radius: 10px !important; background: #f8fafc !important; overflow: visible !important; }
body#layout #outer-wrapper div.section, body#layout .ad-warehouse div.section, body#layout .ad-warehouse-nav div.section { width: 100% !important; max-width: 100% !important; }
body#layout div.section h4 { margin: 0 0 10px !important; padding: 0 2px !important; font-size: 13px !important; font-weight: 700 !important; color: #4f46e5 !important; }
body#layout .ad-warehouse div.section h4, body#layout .ad-warehouse-nav div.section h4 { color: #64748b !important; }
body#layout #Homepage-WebApp-Section { border-color: #a5b4fc !important; background: #eef2ff !important; }
body#layout div.section .widget, body#layout div.section .add_widget, body#layout div.section .dropregion {
  display: block !important; float: none !important; box-sizing: border-box !important; width: 100% !important; max-width: 100% !important; min-width: 0 !important; height: auto !important; margin: 0 0 8px !important; left: auto !important; right: auto !important; }
body#layout div.section .widget-wrap1, body#layout div.section .widget-wrap2, body#layout div.section .widget-wrap3 { box-sizing: border-box !important; width: 100% !important; max-width: 100% !important; margin: 0 !important; }
body#layout div.section .widget:last-child { margin-bottom: 0 !important; }
body#layout div.section .widget-content { box-sizing: border-box !important; width: 100% !important; overflow: hidden !important; }
body#layout .layout-title, body#layout .layout-widget-description { white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important; }
body#layout div.section .add_widget { text-align: center !important; border-radius: 8px !important; }

head.b:skin:
/*
-----------------------------------------------
 DecisionLab 3.0 — 디씨젼랩 · 사이트루미 · 관리형 홈페이지 · 광고 콘텐츠 통합
 기반: Hybrid Split V5.0 (디씨젼랩)  ·  Blogger Layouts v3
 첫 화면 섹션은 「레이아웃」의 HTML 가젯 하나씩 (가젯에서 문구·순서·켜기/끄기)
 여기에는 모든 화면이 함께 쓰는 디자인(토큰·버튼·섹션 틀·글 화면·광고 영역)만 둠
-----------------------------------------------
<Variable name="keycolor" description="포인트 색" type="color" default="#6366f1" value="#6366f1"/>
<Variable name="inkcolor" description="진한 글자·네이비" type="color" default="#0f172a" value="#0f172a"/>
*/

/* [1] 토큰 · 기본 */
:root {
  --dl-point: $(keycolor); --dl-point-d: #4f46e5; --dl-point-l: #818cf8; --dl-point-soft: rgba(99,102,241,.08);
  --dl-ink: $(inkcolor); --dl-text: #1e293b; --dl-sub: #64748b; --dl-mute: #94a3b8; --dl-line: #e2e8f0; --dl-bg: #f8fafc; --dl-card: #fff;
  --dl-ok: #059669; --dl-r: 20px; --dl-r-s: 12px; --dl-shadow: 0 10px 30px rgba(15,23,42,.06); --dl-shadow-h: 0 18px 44px rgba(15,23,42,.12);
  --dl-font: 'Pretendard Variable', Pretendard, -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
  --dl-head: 72px;
}
*, *::before, *::after { box-sizing: border-box; }
html { scroll-padding-top: calc(var(--dl-head) + 12px); scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body { margin: 0; padding: 0; width: 100%; font-family: var(--dl-font); font-size: 16px; line-height: 1.75; letter-spacing: -.01em; color: var(--dl-text); background: #fff; word-break: keep-all; overflow-wrap: break-word; -webkit-font-smoothing: antialiased; overflow-x: hidden; }
h1, h2, h3, h4, h5, h6 { margin: 0; padding: 0; font-weight: 800; color: inherit; }
p { margin: 0; }
a { text-decoration: none; color: inherit; }
img { max-width: 100%; height: auto; display: block; }
button, input, select, textarea { font: inherit; color: inherit; }
.dl-sr { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.dl-skip { position: absolute; left: -9999px; top: 8px; z-index: 20000; padding: 8px 14px; background: #fff; border-radius: 8px; }
.dl-skip:focus { left: 8px; }

/* [2] Blogger 구조 초기화 */
#outer-wrapper, #left-section, .blog-posts { display: block; width: 100%; max-width: 100%; margin: 0; padding: 0; float: none; }
.section, .widget, .widget-content { display: block; width: 100%; max-width: 100%; margin: 0; padding: 0; float: none; }
.widget > h2, .widget-title, .widget .title { display: none !important; }
body.dl-sub #dl-main { padding-top: var(--dl-head); }

/* [3] 공통 섹션 틀 (첫 화면 가젯들이 함께 씀) */
.dl-sec { position: relative; padding: 120px 0; }
.dl-sec.is-soft { background: var(--dl-bg); }
.dl-sec.is-dark { background: var(--dl-ink); color: #fff; }
.dl-in { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.dl-head { max-width: 760px; margin: 0 auto 56px; text-align: center; }
.dl-head.is-left { margin-left: 0; text-align: left; }
.dl-eyebrow { display: inline-block; margin-bottom: 18px; padding: 7px 16px; border-radius: 999px; background: var(--dl-point-soft); color: var(--dl-point); font-size: 14px; font-weight: 800; letter-spacing: .02em; }
.is-dark .dl-eyebrow { background: rgba(129,140,248,.14); color: var(--dl-point-l); }
.dl-h2 { font-size: clamp(30px, 4vw, 46px); line-height: 1.25; letter-spacing: -.035em; font-weight: 900; color: var(--dl-ink); }
.is-dark .dl-h2 { color: #fff; }
.dl-h2 em { font-style: normal; color: var(--dl-point); }
.is-dark .dl-h2 em { color: var(--dl-point-l); }
.dl-lead { margin-top: 18px; font-size: 18px; line-height: 1.85; color: var(--dl-sub); }
.is-dark .dl-lead { color: #94a3b8; }
.dl-hl { color: var(--dl-text); font-weight: 800; box-shadow: inset 0 -.45em 0 rgba(99,102,241,.14); }
.is-dark .dl-hl { color: #fff; box-shadow: inset 0 -.45em 0 rgba(129,140,248,.3); }

/* [4] 버튼 */
.dl-btns { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 32px; }
.dl-btns.is-c { justify-content: center; }
.dl-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 54px; padding: 0 26px; border-radius: 14px; border: 1.5px solid transparent; font-size: 16px; font-weight: 800; letter-spacing: -.01em; cursor: pointer; transition: background .2s, color .2s, border-color .2s, transform .2s, box-shadow .2s; }
.dl-btn:hover { transform: translateY(-2px); }
.dl-btn svg { flex: none; }
.dl-btn small { font-size: 12px; font-weight: 800; padding: 3px 8px; border-radius: 999px; background: rgba(255,255,255,.2); }
.dl-btn-main { background: var(--dl-point); color: #fff !important; box-shadow: 0 10px 24px rgba(99,102,241,.28); }
.dl-btn-main:hover { background: var(--dl-point-d); }
.dl-btn-ink { background: var(--dl-ink); color: #fff !important; }
.dl-btn-ink:hover { background: #1e293b; }
.dl-btn-line { background: #fff; border-color: var(--dl-line); color: var(--dl-text) !important; }
.dl-btn-line:hover { border-color: var(--dl-text); }
.is-dark .dl-btn-line { background: transparent; border-color: rgba(255,255,255,.3); color: #fff !important; }
.is-dark .dl-btn-line:hover { border-color: #fff; }
.dl-btn-block { width: 100%; }

/* [5] 카드 · 칩 · 체크 목록 */
.dl-card { position: relative; background: var(--dl-card); border: 1px solid var(--dl-line); border-radius: var(--dl-r); padding: 32px 28px; transition: transform .25s, box-shadow .25s, border-color .25s; }
.dl-card:hover { transform: translateY(-4px); box-shadow: var(--dl-shadow-h); border-color: transparent; }
.dl-grid { display: grid; gap: 16px; grid-template-columns: 1fr; }
@media (min-width: 680px) { .dl-grid.c2, .dl-grid.c3, .dl-grid.c4 { grid-template-columns: 1fr 1fr; } }
@media (min-width: 1024px) { .dl-grid.c3 { grid-template-columns: repeat(3, 1fr); } .dl-grid.c4 { grid-template-columns: repeat(4, 1fr); } }
.dl-ico { display: inline-grid; place-items: center; width: 52px; height: 52px; border-radius: 16px; background: var(--dl-point-soft); color: var(--dl-point); margin-bottom: 22px; }
.dl-chip { display: inline-flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 48px; padding: 0 16px; border-radius: 12px; background: #fff; border: 1px solid var(--dl-line); font-size: 15px; font-weight: 800; color: var(--dl-text); white-space: nowrap; transition: border-color .2s, color .2s, box-shadow .2s; }
.dl-chip svg { color: var(--dl-point); flex: none; }
.dl-chip:hover { border-color: var(--dl-point); color: var(--dl-point); box-shadow: 0 6px 18px rgba(99,102,241,.14); }
.dl-check { list-style: none; margin: 0; padding: 0; }
.dl-check li { position: relative; padding: 7px 0 7px 26px; font-size: 15px; line-height: 1.6; color: var(--dl-sub); }
.dl-check li::before { content: ''; position: absolute; left: 2px; top: 13px; width: 11px; height: 6px; border-left: 2px solid var(--dl-point); border-bottom: 2px solid var(--dl-point); transform: rotate(-45deg); }
.dl-fine { margin-top: 18px; font-size: 14px; color: var(--dl-mute); line-height: 1.7; }

/* [6] 나타나기 (자바스크립트가 켜질 때만) */
.dl-js .dl-rv { opacity: 0; transform: translateY(26px); transition: opacity .75s cubic-bezier(.2,.7,.2,1), transform .75s cubic-bezier(.2,.7,.2,1); }
.dl-js .dl-rv.in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } .dl-js .dl-rv { opacity: 1; transform: none; transition: none; } }

/* [7] 글 · 정적 페이지 */
.post-outer { max-width: 860px; margin: 0 auto; padding: 48px 24px 0; background: #fff; overflow-x: hidden; }
body.dl-page .post-outer { max-width: 1100px; }
.post-breadcrumb { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; margin-bottom: 18px; font-size: 13.5px; color: var(--dl-mute); }
.post-breadcrumb a { color: var(--dl-sub); }
.post-breadcrumb a:hover { color: var(--dl-point); }
.post-breadcrumb .sep { color: #cbd5e1; }
.post-title { font-size: clamp(28px, 4vw, 40px); font-weight: 900; line-height: 1.3; letter-spacing: -.035em; color: var(--dl-ink); }
.post-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; margin-top: 16px; padding-bottom: 22px; margin-bottom: 32px; border-bottom: 1px solid var(--dl-line); font-size: 14px; color: var(--dl-sub); }
.post-meta .lab { padding: 3px 10px; border-radius: 999px; background: var(--dl-point-soft); color: var(--dl-point); font-weight: 700; font-size: 13px; }
.post-toc { margin: 0 0 36px; padding: 20px 22px; border-radius: var(--dl-r-s); background: var(--dl-bg); border: 1px solid var(--dl-line); }
.post-toc b { display: block; margin-bottom: 8px; font-size: 14px; color: var(--dl-ink); }
.post-toc ol { margin: 0; padding-left: 20px; }
.post-toc li { margin: 4px 0; font-size: 15px; }
.post-toc a { color: var(--dl-sub); }
.post-toc a:hover { color: var(--dl-point); }
.post-body { font-size: 17px; line-height: 1.9; color: #24292f; overflow-wrap: break-word; }
.post-body h2 { margin: 48px 0 16px; font-size: 26px; line-height: 1.4; letter-spacing: -.03em; color: var(--dl-ink); }
.post-body h3 { margin: 36px 0 12px; font-size: 21px; line-height: 1.45; letter-spacing: -.025em; color: var(--dl-ink); }
.post-body h4 { margin: 28px 0 10px; font-size: 18px; }
.post-body p { margin-bottom: 22px; }
.post-body a { color: var(--dl-point-d); text-underline-offset: 3px; }
.post-body ul, .post-body ol { margin: 0 0 22px; padding-left: 1.4em; }
.post-body li { margin: 6px 0; }
.post-body img, .post-body .separator a img { display: block; max-width: 100%; height: auto; margin: 28px auto; border-radius: 10px; }
.post-body figcaption, .tr-caption-container { text-align: center; font-size: .9em; color: #6b7280; }
.post-body blockquote { margin: 28px 0; padding: 18px 22px; border-left: 4px solid var(--dl-point); border-radius: 0 12px 12px 0; background: var(--dl-bg); color: var(--dl-text); }
.post-body table { width: 100%; border-collapse: collapse; margin: 24px 0; font-size: 15px; }
.post-body th, .post-body td { padding: 10px 12px; border: 1px solid var(--dl-line); text-align: left; vertical-align: top; }
.post-body th { background: var(--dl-bg); font-weight: 800; }
.post-body pre { overflow: auto; padding: 16px 18px; border-radius: 12px; background: #0f172a; color: #e2e8f0; font-size: 14px; line-height: 1.6; }
.post-body :not(pre) > code { padding: 1px 6px; border-radius: 6px; background: #f1f5f9; font-size: .92em; }
.post-body iframe { max-width: 100%; }
body.dl-page .post-body { font-size: 16px; line-height: 1.8; }
.post-labels-wrap { display: flex; flex-wrap: wrap; gap: 8px; margin: 36px 0 0; padding-top: 20px; border-top: 1px solid var(--dl-line); }
.post-labels-wrap a { padding: 6px 14px; border-radius: 999px; background: #f1f5f9; color: var(--dl-text); font-size: 14px; font-weight: 700; }
.post-labels-wrap a:hover { background: var(--dl-point-soft); color: var(--dl-point); }
.post-body .cargoda-flat-cta-wrap { display: flex; justify-content: center; margin: 36px 0; }
.post-body a.cargoda-flat-cta, .post-body a.mii-cta-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-width: 280px; max-width: 100%; padding: 15px 28px; border-radius: 14px; background: var(--dl-point); color: #fff !important; font-size: 17px; font-weight: 800; text-decoration: none; box-shadow: 0 10px 24px rgba(99,102,241,.25); }
.post-body a.cargoda-flat-cta:hover { background: var(--dl-point-d); }

/* [8] 글 목록 · 검색 · 페이저 */
.dl-list { max-width: 1200px; margin: 0 auto; padding: 48px 24px 96px; }
.dl-list-head { margin-bottom: 30px; padding-bottom: 22px; border-bottom: 1px solid var(--dl-line); }
.dl-list-head small { color: var(--dl-point); font-weight: 800; font-size: 14px; }
.dl-list-head h1 { margin-top: 6px; font-size: clamp(28px, 4vw, 40px); font-weight: 900; letter-spacing: -.035em; color: var(--dl-ink); }
.dl-cards { display: grid; gap: 18px; grid-template-columns: 1fr; }
@media (min-width: 680px) { .dl-cards { grid-template-columns: 1fr 1fr; } }
@media (min-width: 1024px) { .dl-cards { grid-template-columns: repeat(3, 1fr); } }
.post-card { display: flex; flex-direction: column; overflow: hidden; background: #fff; border: 1px solid var(--dl-line); border-radius: var(--dl-r); transition: transform .25s, box-shadow .25s; }
.post-card:hover { transform: translateY(-4px); box-shadow: var(--dl-shadow-h); }
.post-thumb { aspect-ratio: 16 / 9; overflow: hidden; background: #eef2ff; display: grid; place-items: center; }
.post-thumb img { width: 100%; height: 100%; object-fit: cover; margin: 0; }
.post-thumb b { color: #c7d2fe; font-size: 22px; font-weight: 900; letter-spacing: -.03em; }
.post-info { display: flex; flex-direction: column; gap: 8px; padding: 20px 22px 24px; flex: 1; }
.post-info small { font-size: 13px; font-weight: 800; color: var(--dl-point); }
.post-info h2 { font-size: 18.5px; line-height: 1.45; font-weight: 800; letter-spacing: -.02em; color: var(--dl-ink); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.post-snippet { font-size: 15px; line-height: 1.65; color: var(--dl-sub); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.post-info time { margin-top: auto; font-size: 13px; color: var(--dl-mute); }
.search-post-card { display: flex; justify-content: space-between; gap: 16px; padding: 16px 4px; border-bottom: 1px solid var(--dl-line); }
.search-post-card:hover .search-post-title { color: var(--dl-point); }
.search-post-title { font-size: 16.5px; font-weight: 700; color: var(--dl-text); }
.search-post-date { flex: none; font-size: 13px; color: var(--dl-mute); }
.blog-pager { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 12px; max-width: 860px; margin: 40px auto 0; padding: 0 24px 24px; }
.blog-pager a { display: inline-flex; align-items: center; gap: 8px; min-height: 46px; padding: 0 18px; border-radius: 12px; border: 1px solid var(--dl-line); background: #fff; font-size: 15px; font-weight: 700; color: var(--dl-text); }
.blog-pager a:hover { border-color: var(--dl-point); color: var(--dl-point); }
.blog-pager svg { width: 16px; height: 16px; stroke: currentColor; stroke-width: 2.5; fill: none; }
.dl-empty { padding: 60px 20px; text-align: center; color: var(--dl-mute); border: 1px dashed var(--dl-line); border-radius: var(--dl-r); }
.dl-404 { max-width: 640px; margin: 0 auto; padding: 120px 24px; text-align: center; }
.dl-404 b { display: block; font-size: clamp(80px, 16vw, 160px); line-height: 1; font-weight: 900; letter-spacing: -.05em; color: var(--dl-point); }

/* [9] 광고 영역 (가젯 → 글 안 제자리로 이동) · 애드센스 폭 보정 */
.ad-warehouse, .ad-warehouse-nav { display: none; }
#ad-target-below-title, #ad-target-below-post, #post-bottom-target, #ad-target-below-nextprev, #Post-Top-Ad-Zone, #Post-Middle-Ad-Zone, #Post-Bottom-Ad-Zone, #Below-Nav-Ad-Zone { display: block; width: 100%; max-width: 100%; margin: 0; padding: 0; overflow: hidden; }
#ad-target-below-nextprev { max-width: 860px; margin: 0 auto; padding: 0 24px; }
ins.adsbygoogle, .google-auto-placed { max-width: 100% !important; box-sizing: border-box !important; }
.post-body ins, .post-body .adsbygoogle, #Post-Top-Ad-Zone ins, #Post-Middle-Ad-Zone ins, #Post-Bottom-Ad-Zone ins, #Below-Nav-Ad-Zone ins { display: block !important; width: 100% !important; max-width: 100% !important; min-width: 0 !important; margin: 20px auto !important; float: none !important; }
#comments, .post-comment-link { display: none; }

/* [10] 휴대폰 */
@media (max-width: 768px) {
  :root { --dl-head: 64px; }
  .dl-sec { padding: 80px 0; }
  .dl-in { padding: 0 20px; }
  .dl-head { margin-bottom: 40px; }
  .dl-h2 { font-size: 28px; line-height: 1.35; }
  .dl-lead { font-size: 16.5px; margin-top: 14px; }
  .dl-btns { gap: 8px; margin-top: 26px; }
  .dl-btns .dl-btn { width: 100%; }
  .dl-card { padding: 26px 22px; }
  .post-outer { padding: 30px 20px 0; }
  .post-title { font-size: 26px; }
  .post-body { font-size: 16.5px; line-height: 1.85; }
  .post-body h2 { font-size: 22.5px; margin-top: 40px; }
  .post-body h3 { font-size: 19.5px; }
  .dl-list { padding: 32px 20px 72px; }
  #ad-target-below-nextprev { padding: 0 20px; }
  #outer-wrapper ins.adsbygoogle, #outer-wrapper .google-auto-placed, #outer-wrapper .google-auto-placed > ins { width: 100% !important; max-width: 100% !important; min-width: 0 !important; margin-left: 0 !important; margin-right: 0 !important; left: 0 !important; right: 0 !important; overflow: hidden !important; }
}
@supports (padding: env(safe-area-inset-top)) { @media (display-mode: standalone) { .dl-hd { padding-top: env(safe-area-inset-top); } } }

/* ===== [11] 머리말 (가젯 「01. 머리말」) ===== */
.dl-hd { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; height: var(--dl-head); transition: background .3s, box-shadow .3s, border-color .3s; border-bottom: 1px solid transparent; }
.dl-hd.is-solid, body.dl-sub .dl-hd, body.dl-menu-open .dl-hd { background: rgba(255,255,255,.88); -webkit-backdrop-filter: saturate(180%) blur(14px); backdrop-filter: saturate(180%) blur(14px); border-bottom-color: rgba(226,232,240,.8); }
body.dl-menu-open .dl-hd { background: transparent; border-bottom-color: transparent; -webkit-backdrop-filter: none; backdrop-filter: none; }
.dl-hd-in { display: flex; align-items: center; gap: 28px; max-width: 1280px; height: 100%; margin: 0 auto; padding: 0 24px; }
.dl-logo { font-size: 23px; font-weight: 900; letter-spacing: -.04em; color: var(--dl-ink); white-space: nowrap; }
.dl-logo b { color: var(--dl-point); font-weight: 900; }
.dl-logo.is-light { color: #fff; }
body.dl-menu-open .dl-hd .dl-logo { color: #fff; }
.dl-nav { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.dl-nav a { padding: 8px 12px; border-radius: 10px; font-size: 15px; font-weight: 700; color: #334155; white-space: nowrap; transition: color .2s, background .2s; }
.dl-nav a:hover, .dl-nav a.on { color: var(--dl-point); background: var(--dl-point-soft); }
.dl-hd-act { display: flex; align-items: center; gap: 10px; }
.dl-hd-cta { min-height: 42px; padding: 0 18px; font-size: 15px; border-radius: 12px; box-shadow: none; }
.dl-burger { display: none; position: relative; width: 44px; height: 44px; border: 0; border-radius: 12px; background: transparent; cursor: pointer; }
.dl-burger i { position: absolute; left: 11px; right: 11px; height: 2px; border-radius: 2px; background: var(--dl-ink); transition: transform .3s, opacity .3s, top .3s, background .3s; }
.dl-burger i:nth-child(1) { top: 15px; } .dl-burger i:nth-child(2) { top: 21px; } .dl-burger i:nth-child(3) { top: 27px; }
body.dl-menu-open .dl-burger i { background: #fff; }
body.dl-menu-open .dl-burger i:nth-child(1) { top: 21px; transform: rotate(45deg); }
body.dl-menu-open .dl-burger i:nth-child(2) { opacity: 0; }
body.dl-menu-open .dl-burger i:nth-child(3) { top: 21px; transform: rotate(-45deg); }
.dl-menu { position: fixed; inset: 0; z-index: 999; background: var(--dl-ink); opacity: 0; visibility: hidden; transition: opacity .35s, visibility .35s; overflow-y: auto; }
body.dl-menu-open { overflow: hidden; }
body.dl-menu-open .dl-menu { opacity: 1; visibility: visible; }
.dl-menu-in { display: flex; flex-direction: column; max-width: 560px; margin: 0 auto; padding: calc(var(--dl-head) + 24px) 28px 48px; }
.dl-menu-in > a { display: flex; align-items: baseline; gap: 14px; padding: 14px 0; border-bottom: 1px solid rgba(255,255,255,.08); font-size: 24px; font-weight: 800; letter-spacing: -.03em; color: #fff; transform: translateY(12px); opacity: 0; transition: transform .45s, opacity .45s, color .2s; }
.dl-menu-in > a small { font-size: 13px; font-weight: 800; color: var(--dl-point-l); }
.dl-menu-in > a:hover { color: var(--dl-point-l); }
body.dl-menu-open .dl-menu-in > a { transform: none; opacity: 1; }
.dl-menu-cta { display: grid; gap: 10px; margin-top: 30px; }
.dl-menu-cta .dl-btn-line { background: transparent; border-color: rgba(255,255,255,.3); color: #fff !important; }
.dl-menu-tel { margin-top: 22px; font-size: 14px; color: #94a3b8; }
.dl-menu-tel a { color: #e2e8f0; font-weight: 700; }
@media (max-width: 1080px) { .dl-nav, .dl-hd-cta { display: none; } .dl-burger { display: block; } .dl-hd-act { margin-left: auto; } }

/* ===== [12] 첫 화면 (가젯 「02. 첫 화면」) ===== */
.dl-hero { position: relative; overflow: hidden; padding: calc(var(--dl-head) + 72px) 0 72px; background: radial-gradient(1000px 520px at 85% -10%, rgba(99,102,241,.13), transparent 60%), radial-gradient(700px 400px at -10% 30%, rgba(129,140,248,.1), transparent 60%), #fff; }
.dl-hero-grid { display: grid; grid-template-columns: 1.08fr .92fr; gap: 48px; align-items: center; }
.dl-hero-q { display: inline-flex; align-items: center; gap: 8px; margin-bottom: 22px; padding: 8px 16px; border-radius: 999px; background: #fff; border: 1px solid var(--dl-line); box-shadow: var(--dl-shadow); font-size: 14.5px; font-weight: 700; color: var(--dl-sub); }
.dl-hero-q::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--dl-point); box-shadow: 0 0 0 4px rgba(99,102,241,.18); }
.dl-h1 { font-size: clamp(38px, 5.4vw, 66px); line-height: 1.18; letter-spacing: -.045em; font-weight: 900; color: var(--dl-ink); }
.dl-h1 em { font-style: normal; color: var(--dl-point); }
.dl-m { display: none; }
.dl-hero-lead { margin-top: 24px; max-width: 560px; font-size: 18.5px; line-height: 1.85; color: var(--dl-sub); }
.dl-hero-lead b { color: var(--dl-text); }
.dl-hero-facts { display: flex; flex-wrap: wrap; gap: 0; margin: 40px 0 0; padding: 0; list-style: none; }
.dl-hero-facts li { display: flex; flex-direction: column; gap: 2px; padding: 0 26px; border-left: 1px solid var(--dl-line); }
.dl-hero-facts li:first-child { padding-left: 0; border-left: 0; }
.dl-hero-facts b { font-size: 20px; font-weight: 900; letter-spacing: -.03em; color: var(--dl-ink); }
.dl-hero-facts span { font-size: 13.5px; color: var(--dl-mute); }
.dl-hero-art { position: relative; height: 460px; }
.dl-mock { position: absolute; top: 20px; left: 0; right: 40px; border-radius: 18px; background: #fff; border: 1px solid var(--dl-line); box-shadow: 0 30px 70px rgba(15,23,42,.14); overflow: hidden; animation: dl-up 1s cubic-bezier(.2,.7,.2,1) both; }
.dl-mock-bar { display: flex; align-items: center; gap: 6px; height: 38px; padding: 0 14px; border-bottom: 1px solid var(--dl-line); background: var(--dl-bg); }
.dl-mock-bar i { width: 9px; height: 9px; border-radius: 50%; background: #cbd5e1; }
.dl-mock-bar span { margin-left: 10px; padding: 3px 12px; border-radius: 999px; background: #fff; font-size: 11.5px; color: var(--dl-mute); }
.dl-mock-body { padding: 20px; }
.dl-mock-hero { height: 150px; border-radius: 12px; padding: 26px 22px; background: linear-gradient(135deg, #0f172a, #312e81); }
.dl-mock-hero b, .dl-mock-lines b { display: block; height: 12px; width: 62%; border-radius: 6px; background: rgba(255,255,255,.85); margin-bottom: 10px; }
.dl-mock-hero b.s { width: 40%; background: rgba(255,255,255,.4); }
.dl-mock-hero span { display: inline-block; margin-top: 18px; width: 96px; height: 30px; border-radius: 8px; background: var(--dl-point); }
.dl-mock-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 14px 0; }
.dl-mock-row i { height: 62px; border-radius: 10px; background: #eef2ff; }
.dl-mock-lines b { background: #e2e8f0; height: 9px; width: 90%; }
.dl-mock-lines b.s { width: 55%; }
.dl-phone { position: absolute; right: 0; bottom: 0; width: 170px; height: 330px; padding: 10px; border-radius: 30px; background: var(--dl-ink); box-shadow: 0 30px 60px rgba(15,23,42,.3); animation: dl-up 1s .15s cubic-bezier(.2,.7,.2,1) both; }
.dl-phone-in { height: 100%; border-radius: 22px; background: #fff; padding: 22px 14px; overflow: hidden; }
.dl-phone-in i { display: block; width: 46px; height: 46px; border-radius: 50%; background: linear-gradient(135deg, var(--dl-point), var(--dl-point-l)); margin: 6px auto 14px; }
.dl-phone-in b { display: block; height: 9px; width: 70%; margin: 0 auto 8px; border-radius: 5px; background: #cbd5e1; }
.dl-phone-in b.s { width: 46%; background: #e2e8f0; }
.dl-phone-in span { display: block; height: 34px; margin-top: 12px; border-radius: 9px; background: #eef2ff; }
.dl-float { position: absolute; display: inline-flex; align-items: center; gap: 8px; padding: 11px 16px; border-radius: 14px; background: #fff; border: 1px solid var(--dl-line); box-shadow: var(--dl-shadow-h); font-size: 14px; font-weight: 800; color: var(--dl-text); animation: dl-bob 5s ease-in-out infinite; }
.dl-float svg { color: var(--dl-ok); }
.dl-float-a { left: -18px; bottom: 70px; }
.dl-float-b { right: 120px; top: -6px; animation-delay: -2.5s; }
.dl-float-b svg { color: var(--dl-point); }
@keyframes dl-up { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: none; } }
@keyframes dl-bob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
.dl-quick { display: flex; align-items: center; gap: 20px; margin-top: 56px; padding: 18px 20px; border-radius: var(--dl-r); background: #fff; border: 1px solid var(--dl-line); box-shadow: var(--dl-shadow); }
.dl-quick-head { flex: none; display: flex; flex-direction: column; }
.dl-quick-head b { font-size: 16px; font-weight: 900; color: var(--dl-ink); }
.dl-quick-head span { font-size: 13px; color: var(--dl-mute); }
.dl-quick-list { display: flex; flex-wrap: wrap; gap: 8px; }
.dl-quick-list .dl-chip { min-height: 42px; font-size: 14.5px; }
@media (max-width: 1024px) {
  .dl-hero-grid { grid-template-columns: 1fr; }
  .dl-hero-art { height: 380px; max-width: 520px; width: 100%; margin: 0 auto; }
  .dl-quick { flex-direction: column; align-items: stretch; }
}
@media (max-width: 768px) {
  .dl-hero { padding: calc(var(--dl-head) + 40px) 0 56px; }
  .dl-h1 { font-size: 36px; line-height: 1.25; }
  .dl-m { display: inline; }
  .dl-hero-q { font-size: 13px; padding: 7px 13px; margin-bottom: 18px; }
  .dl-hero-lead { font-size: 16.5px; margin-top: 18px; }
  .dl-hero-facts { display: grid; grid-template-columns: repeat(3, 1fr); margin-top: 32px; }
  .dl-hero-facts li { padding: 0 10px; }
  .dl-hero-facts b { font-size: 16px; }
  .dl-hero-facts span { font-size: 12px; }
  .dl-hero-art { display: none; }
  .dl-quick { margin-top: 36px; padding: 18px 16px; gap: 14px; }
  .dl-quick-list { display: grid; grid-template-columns: 1fr 1fr; }
  .dl-quick-list .dl-chip { white-space: normal; text-align: left; }
}

/* ===== [13] 흐르는 띠 ===== */
.dl-marquee { overflow: hidden; padding: 22px 0; background: var(--dl-ink); }
.dl-marquee-in { display: flex; align-items: center; gap: 28px; width: max-content; animation: dl-mq 38s linear infinite; }
.dl-marquee span { font-size: 18px; font-weight: 900; letter-spacing: .04em; color: #fff; white-space: nowrap; }
.dl-marquee i { width: 8px; height: 8px; border-radius: 50%; background: var(--dl-point-l); }
@keyframes dl-mq { to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) { .dl-marquee-in { animation: none; } .dl-float, .dl-mock, .dl-phone { animation: none; } }

/* ===== [14] 카드 묶음 (왜·서비스) ===== */
.dl-card h3 { font-size: 21px; line-height: 1.4; letter-spacing: -.025em; color: var(--dl-ink); margin-bottom: 10px; }
.dl-card p { font-size: 15.5px; line-height: 1.75; color: var(--dl-sub); }
.dl-card-k { display: block; margin-bottom: 6px; font-size: 13.5px; font-weight: 800; color: var(--dl-point); }
.dl-svc .dl-card { display: flex; flex-direction: column; }
.dl-svc-no { font-size: 13px; font-weight: 800; color: var(--dl-mute); margin-bottom: 14px; }
.dl-svc-price { margin-top: 18px !important; font-size: 19px !important; font-weight: 900; color: var(--dl-ink) !important; }
.dl-svc-price span { font-size: 13.5px; font-weight: 700; color: var(--dl-mute); }
.dl-svc-go { display: inline-flex; align-items: center; gap: 6px; margin-top: auto; padding-top: 22px; font-size: 15px; font-weight: 800; color: var(--dl-point); }
.dl-svc .is-pick { background: var(--dl-ink); border-color: var(--dl-ink); }
.dl-svc .is-pick h3, .dl-svc .is-pick .dl-svc-price { color: #fff !important; }
.dl-svc .is-pick p { color: #94a3b8; }
.dl-svc .is-pick .dl-svc-go { color: var(--dl-point-l); }

/* ===== [15] 사이트루미 ===== */
.dl-split { display: grid; grid-template-columns: .9fr 1.1fr; gap: 64px; align-items: center; }
.dl-split .dl-head { margin-bottom: 0; }
.dl-feats { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.dl-feat { display: flex; flex-direction: column; padding: 26px 24px; border-radius: var(--dl-r); background: var(--dl-bg); border: 1px solid var(--dl-line); }
.dl-feat .dl-ico { width: 46px; height: 46px; margin-bottom: 16px; background: #fff; }
.dl-feat h3 { font-size: 18px; color: var(--dl-ink); margin-bottom: 6px; }
.dl-feat p { font-size: 15px; line-height: 1.7; color: var(--dl-sub); }
@media (max-width: 1024px) { .dl-split { grid-template-columns: 1fr; gap: 40px; } }
@media (max-width: 560px) { .dl-feats { grid-template-columns: 1fr; } .dl-feat { flex-direction: row; gap: 16px; padding: 20px; } .dl-feat .dl-ico { flex: none; margin: 0; } }

/* ===== [16] 가격 · 관리형 ===== */
.dl-prices { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; align-items: stretch; }
.dl-price { position: relative; display: flex; flex-direction: column; padding: 30px 24px; border-radius: var(--dl-r); background: #fff; border: 1px solid var(--dl-line); }
.dl-price h3 { font-size: 17px; font-weight: 800; color: var(--dl-sub); }
.dl-won { margin: 8px 0 4px; font-size: 34px; font-weight: 900; letter-spacing: -.04em; color: var(--dl-ink); line-height: 1.2; }
.dl-won small { margin-left: 2px; font-size: 16px; font-weight: 700; color: var(--dl-sub); letter-spacing: 0; }
.dl-pdesc { font-size: 14.5px; color: var(--dl-mute); margin-bottom: 18px; }
.dl-price .dl-check { flex: 1; margin-bottom: 24px; }
.dl-price .dl-check b { color: var(--dl-text); }
.dl-price.is-best { border: 2px solid var(--dl-point); box-shadow: 0 18px 44px rgba(99,102,241,.18); }
.dl-badge { position: absolute; top: -14px; left: 24px; padding: 5px 12px; border-radius: 999px; background: var(--dl-point); color: #fff; font-size: 12.5px; font-weight: 800; }
.dl-custom { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin-top: 14px; padding: 26px 28px; border-radius: var(--dl-r); background: #fff; border: 1px dashed #c7d2fe; }
.dl-custom h3 { font-size: 19px; color: var(--dl-ink); }
.dl-custom h3 span { margin-left: 8px; color: var(--dl-point); }
.dl-custom p { margin-top: 4px; font-size: 15px; color: var(--dl-sub); }
.dl-custom .dl-btn { flex: none; }
.dl-managed { display: grid; grid-template-columns: 1.4fr 1fr; gap: 40px; align-items: center; margin-top: 40px; padding: 44px; border-radius: 28px; background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%); color: #fff; scroll-margin-top: calc(var(--dl-head) + 20px); }
.dl-managed .dl-eyebrow { background: rgba(129,140,248,.16); color: var(--dl-point-l); }
.dl-managed h3 { font-size: clamp(24px, 3vw, 32px); line-height: 1.35; letter-spacing: -.035em; }
.dl-managed-copy > p { margin: 14px 0 18px; font-size: 16px; color: #cbd5e1; }
.dl-managed .dl-check li { color: #e2e8f0; }
.dl-managed .dl-check li::before { border-color: var(--dl-point-l); }
.dl-managed-price { padding: 28px; border-radius: var(--dl-r); background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12); }
.dl-managed-price .dl-won { color: #fff; }
.dl-managed-price .dl-won small { color: #cbd5e1; }
.dl-managed-price .dl-pdesc { color: #94a3b8; }
.dl-center { text-align: center; }
@media (max-width: 1100px) { .dl-prices { grid-template-columns: 1fr 1fr; } }
@media (max-width: 860px) { .dl-managed { grid-template-columns: 1fr; padding: 32px 24px; gap: 24px; } .dl-custom { flex-direction: column; align-items: stretch; } }
@media (max-width: 560px) { .dl-prices { grid-template-columns: 1fr; gap: 18px; } .dl-won { font-size: 30px; } }

/* ===== [17] 진행 순서 ===== */
.dl-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin: 0; padding: 0; list-style: none; counter-reset: s; }
.dl-steps li { position: relative; padding: 32px 28px; border-radius: var(--dl-r); background: #fff; border: 1px solid var(--dl-line); }
.dl-steps b { display: inline-grid; place-items: center; width: 44px; height: 44px; margin-bottom: 18px; border-radius: 14px; background: var(--dl-ink); color: #fff; font-size: 15px; font-weight: 900; }
.dl-steps h3 { font-size: 20px; color: var(--dl-ink); margin-bottom: 8px; }
.dl-steps p { font-size: 15.5px; line-height: 1.75; color: var(--dl-sub); }
.dl-steps strong { color: var(--dl-point); }
@media (max-width: 860px) { .dl-steps { grid-template-columns: 1fr; } }

/* ===== [18] 광고 콘텐츠 ===== */
.dl-goods { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.dl-good { display: flex; flex-direction: column; gap: 8px; padding: 26px 24px; border-radius: var(--dl-r); background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.1); transition: background .25s, border-color .25s, transform .25s; }
.dl-good:hover { background: rgba(129,140,248,.1); border-color: rgba(129,140,248,.5); transform: translateY(-3px); }
.dl-good b { font-size: 19px; font-weight: 800; color: #fff; }
.dl-good span { font-size: 15px; line-height: 1.65; color: #94a3b8; }
.dl-good small { display: inline-flex; align-items: center; gap: 6px; margin-top: auto; padding-top: 10px; font-size: 14px; font-weight: 800; color: var(--dl-point-l); }
.dl-good em { font-style: normal; font-size: 13px; color: #cbd5e1; }
@media (max-width: 960px) { .dl-goods { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .dl-goods { grid-template-columns: 1fr; } }

/* ===== [19] 글 묶음 (포트폴리오·인사이트) ===== */
.dl-feed .dl-empty { grid-column: 1 / -1; }

/* ===== [20] 무료 도구 ===== */
.dl-tool { padding: 26px 24px; border-radius: var(--dl-r); background: #fff; border: 1px solid var(--dl-line); }
.dl-tool h3 { display: flex; align-items: center; gap: 8px; margin-bottom: 14px; font-size: 17px; color: var(--dl-ink); }
.dl-tool h3 svg { color: var(--dl-point); }
.dl-tool a { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-top: 1px solid #f1f5f9; font-size: 15px; font-weight: 600; color: var(--dl-sub); transition: color .2s; }
.dl-tool a::after { content: ''; width: 7px; height: 7px; border-top: 2px solid currentColor; border-right: 2px solid currentColor; transform: rotate(45deg); opacity: .4; }
.dl-tool a:hover { color: var(--dl-point); }

/* ===== [21] 자주 묻는 질문 ===== */
.dl-faqwrap { display: grid; grid-template-columns: .8fr 1.2fr; gap: 56px; align-items: start; }
.dl-faq { border-bottom: 1px solid var(--dl-line); }
.dl-faq summary { position: relative; padding: 22px 40px 22px 0; list-style: none; cursor: pointer; font-size: 17.5px; font-weight: 800; line-height: 1.5; color: var(--dl-ink); }
.dl-faq summary::-webkit-details-marker { display: none; }
.dl-faq summary::after { content: ''; position: absolute; right: 6px; top: 30px; width: 10px; height: 10px; border-right: 2px solid var(--dl-sub); border-bottom: 2px solid var(--dl-sub); transform: rotate(45deg); transition: transform .25s; }
.dl-faq[open] summary::after { transform: rotate(-135deg); top: 34px; }
.dl-faq p { padding: 0 0 22px; font-size: 16px; line-height: 1.85; color: var(--dl-sub); }
@media (max-width: 860px) { .dl-faqwrap { grid-template-columns: 1fr; gap: 20px; } .dl-faq summary { font-size: 16.5px; padding: 18px 36px 18px 0; } .dl-faq summary::after { top: 26px; } }

/* ===== [22] 상담 신청 ===== */
.dl-contact { display: grid; grid-template-columns: .9fr 1.1fr; gap: 56px; align-items: start; }
.dl-contact .dl-head, .dl-contact-copy { text-align: left; }
.dl-contact-info { margin: 32px 0 0; padding: 0; list-style: none; }
.dl-contact-info li { display: flex; gap: 16px; padding: 14px 0; border-top: 1px solid rgba(255,255,255,.1); font-size: 16px; color: #e2e8f0; }
.dl-contact-info span { width: 80px; flex: none; color: #94a3b8; font-size: 14.5px; }
.dl-contact-info a { color: #fff; font-weight: 700; }
.dl-form { display: grid; gap: 14px; padding: 32px; border-radius: 24px; background: #fff; color: var(--dl-text); box-shadow: 0 30px 70px rgba(0,0,0,.25); }
.dl-form label > span, .dl-form legend { display: block; margin-bottom: 6px; font-size: 14px; font-weight: 800; color: var(--dl-text); }
.dl-form label > span b { color: var(--dl-point); }
.dl-form input:not([type=checkbox]), .dl-form textarea { width: 100%; min-height: 50px; padding: 12px 14px; border-radius: 12px; border: 1.5px solid var(--dl-line); background: var(--dl-bg); font-size: 16px; outline: none; transition: border-color .2s, background .2s; }
.dl-form textarea { resize: vertical; min-height: 110px; line-height: 1.6; }
.dl-form input:focus, .dl-form textarea:focus { border-color: var(--dl-point); background: #fff; }
.dl-f2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.dl-wants { margin: 0; padding: 0; border: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.dl-wants legend { width: 100%; }
.dl-wants label { cursor: pointer; }
.dl-wants input { position: absolute; opacity: 0; pointer-events: none; }
.dl-wants span { display: inline-flex; align-items: center; min-height: 40px; line-height: 1.2; padding: 0 14px; border-radius: 999px; border: 1.5px solid var(--dl-line); font-size: 14.5px; font-weight: 700; color: var(--dl-sub); transition: all .2s; }
.dl-wants input:checked + span { border-color: var(--dl-point); background: var(--dl-point-soft); color: var(--dl-point); }
.dl-wants input:focus-visible + span { outline: 2px solid var(--dl-point); outline-offset: 2px; }
.dl-agree { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; color: var(--dl-sub); cursor: pointer; }
.dl-agree input { width: 18px; height: 18px; margin-top: 2px; accent-color: var(--dl-point); flex: none; }
.dl-agree span { font-weight: 500 !important; margin: 0 !important; color: var(--dl-sub) !important; }
.dl-link { padding: 0; border: 0; background: none; color: var(--dl-point); font-weight: 700; text-decoration: underline; cursor: pointer; font-size: inherit; }
.dl-hp { position: absolute !important; left: -9999px !important; }
.dl-form-msg { min-height: 1.4em; font-size: 14.5px; font-weight: 700; text-align: center; }
.dl-form-msg.ok { color: var(--dl-ok); } .dl-form-msg.err { color: #dc2626; }
.dl-form .dl-btn[disabled] { opacity: .6; cursor: wait; transform: none; }
@media (max-width: 960px) { .dl-contact { grid-template-columns: 1fr; gap: 36px; } }
@media (max-width: 560px) { .dl-form { padding: 24px 18px; border-radius: 20px; } .dl-f2 { grid-template-columns: 1fr; } }

/* ===== [23] 꼬리말 · 약관 창 ===== */
.dl-ft { padding: 72px 0 40px; background: #0b1120; color: #94a3b8; font-size: 14.5px; }
.dl-ft-top { display: flex; justify-content: space-between; gap: 48px; padding-bottom: 40px; border-bottom: 1px solid rgba(255,255,255,.08); }
.dl-ft-brand p { margin-top: 12px; max-width: 340px; line-height: 1.7; }
.dl-ft-nav { display: grid; grid-template-columns: repeat(3, auto); gap: 56px; }
.dl-ft-nav h4 { margin-bottom: 14px; font-size: 13px; font-weight: 800; letter-spacing: .06em; color: #fff; }
.dl-ft-nav a, .dl-ft-nav button { display: block; padding: 5px 0; border: 0; background: none; font-size: 14.5px; color: #94a3b8; cursor: pointer; text-align: left; transition: color .2s; }
.dl-ft-nav a:hover, .dl-ft-nav button:hover { color: #fff; }
.dl-ft-info { display: flex; flex-wrap: wrap; gap: 6px 18px; padding-top: 28px; font-style: normal; font-size: 13.5px; line-height: 1.7; }
.dl-ft-info a { color: #cbd5e1; }
.dl-ft-copy { margin-top: 16px; font-size: 13px; color: #64748b; }
.dl-modal { position: fixed; inset: 0; z-index: 3000; display: grid; place-items: center; padding: 20px; background: rgba(15,23,42,.6); -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px); }
.dl-modal[hidden] { display: none; }
.dl-modal-box { width: 100%; max-width: 560px; max-height: 80vh; display: flex; flex-direction: column; border-radius: 22px; background: #fff; overflow: hidden; }
.dl-modal-head { display: flex; align-items: center; justify-content: space-between; padding: 20px 24px; border-bottom: 1px solid var(--dl-line); }
.dl-modal-head h3 { font-size: 18px; color: var(--dl-ink); }
.dl-modal-x { width: 40px; height: 40px; border: 0; border-radius: 10px; background: var(--dl-bg); cursor: pointer; display: grid; place-items: center; color: var(--dl-sub); }
.dl-modal-body { padding: 22px 24px 28px; overflow-y: auto; white-space: pre-line; font-size: 15px; line-height: 1.85; color: var(--dl-sub); }
@media (max-width: 860px) { .dl-ft { padding: 56px 0 32px; } .dl-ft-top { flex-direction: column; gap: 32px; } .dl-ft-nav { grid-template-columns: repeat(3, 1fr); gap: 20px; } }
@media (max-width: 480px) { .dl-ft-nav { grid-template-columns: 1fr 1fr; } .dl-ft-info { flex-direction: column; gap: 2px; } }

/* ===== [24] 글 아래 상담 띠 (글 화면) ===== */
.dl-post-cta { max-width: 860px; margin: 48px auto 0; padding: 0 24px; }
.dl-post-cta-in { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 26px 28px; border-radius: var(--dl-r); background: var(--dl-ink); color: #fff; }
.dl-post-cta b { display: block; font-size: 18px; letter-spacing: -.02em; }
.dl-post-cta span { font-size: 14.5px; color: #94a3b8; }
.dl-post-cta .dl-btn { flex: none; min-height: 48px; }
@media (max-width: 640px) { .dl-post-cta { padding: 0 20px; } .dl-post-cta-in { flex-direction: column; align-items: stretch; text-align: left; } }

head.script:
//
  /* 휴대폰 주소의 ?m=1 지우기 */
  (function () { var u = location.toString(); if (u.indexOf('?m=1') > 0 || u.indexOf('&m=1') > 0) history.replaceState({}, document.title, u.replace(/[?&]m=1/g, '')); })();
  /* 사이트 설정 — 접수 GAS(상담·자료 받기) · 사이트루미 체험 편집기 (비밀 값 아님) */
  window.DLX = {
    intake: 'https://script.google.com/macros/s/AKfycbzcRM7Tpexe8vIsD-BTCnt72o-e69Cq4voBpXonPnlOytdi_noXjs1RqwghNKMhJSV8xA/exec',
    demo: 'https://script.google.com/macros/s/AKfycbzFZbRfzsYouLT2P0mSfzg6AG9kagjug4G2AsPH8qae4_Qn8k59LUsRaxoiQpMUCMfG/exec?demo=1'
  };
  /* 관리 화면: 주소 끝 #dcadmin 일 때만 불러옴 (검색에 안 잡힘 · 키는 브라우저에만) */
  (function () { function go() { if (/^#dcadmin/.test(location.hash) && !window.__dcAdmin && !document.getElementById('dc-admin-js')) { var s = document.createElement('script'); s.id = 'dc-admin-js'; s.src = 'https://cdn.jsdelivr.net/gh/hoonk740-dotcom/sitelumi-design@main/admin/dc-admin.js'; document.head.appendChild(s); } } go(); window.addEventListener('hashchange', go); })();
//

body.script:
//
/* 디씨젼랩 3.0 — 모든 화면 공통 동작 (가젯은 글·구조만, 동작은 여기서) */
(function () {
  'use strict';
  var D = document, W = window, X = W.DLX || {};
  var $ = function (s, r) { return (r || D).querySelector(s); }, $$ = function (s, r) { return Array.prototype.slice.call((r || D).querySelectorAll(s)); };
  var esc = function (t) { return String(t == null ? '' : t).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var ARROW = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M7 17L17 7M9 7h8v8"/></svg>';
  D.documentElement.classList.add('dl-js');

  /* 1. 머리말: 스크롤하면 흰 바탕 · 메뉴 열기/닫기 · 지금 보는 섹션 표시 */
  var hd = $('#dlHd'), burger = $('#dlBurger'), menu = $('#dlMenu');
  function onScroll() { if (hd) hd.classList.toggle('is-solid', W.scrollY > 12); }
  onScroll(); W.addEventListener('scroll', onScroll, { passive: true });
  function setMenu(open) {
    D.body.classList.toggle('dl-menu-open', open);
    if (burger) { burger.setAttribute('aria-expanded', open ? 'true' : 'false'); burger.setAttribute('aria-label', open ? '메뉴 닫기' : '메뉴 열기'); }
    if (menu) menu.setAttribute('aria-hidden', open ? 'false' : 'true');
  }
  if (burger) burger.addEventListener('click', function () { setMenu(!D.body.classList.contains('dl-menu-open')); });
  if (menu) menu.addEventListener('click', function (e) { if (e.target.closest('a')) setMenu(false); });
  D.addEventListener('keydown', function (e) { if (e.key === 'Escape') { setMenu(false); closeModal(); } });
  if ('IntersectionObserver' in W) {
    var navs = $$('.dl-nav a'), map = {};
    navs.forEach(function (a) { var h = (a.getAttribute('href') || '').split('#')[1]; if (h) map[h] = a; });
    var spy = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting && map[en.target.id]) { navs.forEach(function (a) { a.classList.remove('on'); }); map[en.target.id].classList.add('on'); } }); }, { rootMargin: '-45% 0px -50% 0px' });
    Object.keys(map).forEach(function (id) { var el = D.getElementById(id); if (el) spy.observe(el); });
  }

  /* 2. 나타나기 */
  function reveal(root) {
    var els = $$('.dl-rv:not(.in)', root);
    if (!('IntersectionObserver' in W)) { els.forEach(function (el) { el.classList.add('in'); }); return; }
    var io = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } }); }, { rootMargin: '0px 0px -8% 0px' });
    els.forEach(function (el) { io.observe(el); });
  }
  reveal();

  /* 3. 버튼 주소: 체험 편집기 · 접수 폼 · 상담 칸으로 */
  $$('[data-dl-demo]').forEach(function (a) { if (X.demo) a.href = X.demo; else a.removeAttribute('target'); });
  $$('[data-dl-intake]').forEach(function (a) {
    if (!X.intake) return;
    a.href = X.intake + '?s=' + encodeURIComponent(a.getAttribute('data-dl-intake')) + (a.getAttribute('data-plan') ? '&plan=' + encodeURIComponent(a.getAttribute('data-plan')) : '') + '&from=dlx';
    a.target = '_blank'; a.rel = 'noopener';
  });
  D.addEventListener('click', function (e) {
    var a = e.target.closest('[data-dl-ask]'), f = $('#dlAsk');
    if (!a || !f) return;
    e.preventDefault();
    var v = a.getAttribute('data-dl-ask'), cb = f.querySelector('input[name=wants][value="' + v + '"]');
    if (cb) cb.checked = true;
    f.elements.plan.value = a.getAttribute('data-plan') || '';
    $('#contact').scrollIntoView({ behavior: 'smooth' });
    setTimeout(function () { f.elements.who.focus({ preventScroll: true }); }, 600);
  });

  /* 4. 광고 콘텐츠 목록 — 접수 GAS 상품 목록으로 늘 최신 (못 읽으면 가젯에 적힌 기본 목록 그대로) */
  var goodsBoxes = $$('[data-dl-goods]');
  if (goodsBoxes.length && X.intake) {
    fetch(X.intake + '?a=catalog').then(function (r) { return r.json(); }).then(function (c) {
      if (!c || !c.ok || !c.products || !c.products.length) return;
      var list = c.products.filter(function (p) { return p.id !== 'homepage'; });
      goodsBoxes.forEach(function (box) {
        var kind = box.getAttribute('data-dl-goods');
        box.innerHTML = list.map(function (p) {
          var href = X.intake + '?s=' + encodeURIComponent(p.id) + '&from=dlx';
          if (kind === 'chips') return '<a class="dl-chip" href="' + esc(href) + '" target="_blank" rel="noopener" title="' + esc(p.desc) + '">' + esc(p.name) + ARROW + '</a>';
          return '<a class="dl-good dl-rv" href="' + esc(href) + '" target="_blank" rel="noopener"><b>' + esc(p.name) + '</b><span>' + esc(p.desc) + '</span>' + (p.price ? '<em>' + esc(p.price) + '</em>' : '') + '<small>자료 보내기 ' + ARROW + '</small></a>';
        }).join('');
        reveal(box);
      });
    }).catch(function () {});
  }

  /* 5. 글 묶음 (포트폴리오·인사이트) — 블로그 글 목록에서 */
  $$('[data-dl-feed]').forEach(function (box) {
    var label = box.getAttribute('data-dl-feed'), max = +box.getAttribute('data-max') || 6, skip = box.getAttribute('data-skip') || '';
    var url = '/feeds/posts/default' + (label ? '/-/' + encodeURIComponent(label) : '') + '?alt=json&max-results=' + (max + (skip ? 12 : 0));
    fetch(url).then(function (r) { return r.json(); }).then(function (j) {
      var es = (j.feed && j.feed.entry) || [];
      es = es.filter(function (e) { return !skip || !(e.category || []).some(function (c) { return c.term === skip; }); }).slice(0, max);
      if (!es.length) { if (!box.querySelector('.post-card')) box.innerHTML = '<p class="dl-empty">아직 글이 없어요.</p>'; return; }
      box.innerHTML = es.map(function (e) {
        var link = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0] || {};
        var th = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/w640-h360-c/').replace(/=s\d+(-c)?$/, '=w640-h360-c') : '';
        var lab = (e.category || [])[0], sum = (e.summary ? e.summary.$t : (e.content ? e.content.$t.replace(/<[^>]+>/g, ' ') : '')).replace(/\s+/g, ' ').trim().slice(0, 110);
        var d = (e.published && e.published.$t || '').slice(0, 10).replace(/-/g, '. ');
        return '<a class="post-card dl-rv" href="' + esc(link.href) + '"><div class="post-thumb">' + (th ? '<img src="' + esc(th) + '" alt="' + esc(e.title.$t) + '" loading="lazy" width="640" height="360">' : '<b>DecisionLAB</b>') + '</div>' +
          '<div class="post-info">' + (lab ? '<small>' + esc(lab.term) + '</small>' : '') + '<h2>' + esc(e.title.$t) + '</h2>' + (sum ? '<p class="post-snippet">' + esc(sum) + '</p>' : '') + (d ? '<time>' + d + '</time>' : '') + '</div></a>';
      }).join('');
      reveal(box);
    }).catch(function () {});
  });

  /* 6. 자주 묻는 질문 → 검색엔진·AI 답변용 FAQ 정보 (AEO) */
  var faq = $('[data-dl-faq]');
  if (faq) {
    var qa = $$('details', faq).map(function (d) { var s = $('summary', d), p = $('p', d); return s && p ? { '@type': 'Question', name: s.textContent.trim(), acceptedAnswer: { '@type': 'Answer', text: p.textContent.trim() } } : null; }).filter(Boolean);
    if (qa.length) { var ld = D.createElement('script'); ld.type = 'application/ld+json'; ld.text = JSON.stringify({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: qa }); D.head.appendChild(ld); }
  }

  /* 7. 상담 신청 → 접수 GAS (디씨젼랩 관리 화면 「문의」) */
  var form = $('#dlAsk');
  if (form) form.addEventListener('submit', function (e) {
    e.preventDefault();
    var msg = $('.dl-form-msg', form), btn = $('button[type=submit]', form), el = form.elements;
    var say = function (t, ok) { msg.textContent = t; msg.className = 'dl-form-msg ' + (ok ? 'ok' : 'err'); };
    if (!el.who.value.trim()) { say('이름이나 상호를 적어 주세요.'); el.who.focus(); return; }
    if (!/\d{2,}.*\d{3,}/.test(el.phone.value)) { say('연락받을 전화번호를 적어 주세요.'); el.phone.focus(); return; }
    if (!el.msg.value.trim()) { say('문의 내용을 적어 주세요.'); el.msg.focus(); return; }
    if (!el.agree.checked) { say('개인정보 수집·이용에 동의해 주세요.'); return; }
    if (!X.intake) { say('지금은 보낼 수 없어요. 전화나 메일로 연락 주세요.'); return; }
    var data = { who: el.who.value, phone: el.phone.value, email: el.email.value, msg: el.msg.value, plan: el.plan.value, agree: true, website: el.website.value,
      wants: $$('input[name=wants]:checked', form).map(function (c) { return c.value; }), from: '홈 상담' };
    btn.disabled = true; say('보내는 중이에요…', true);
    fetch(X.intake, { method: 'POST', body: JSON.stringify({ a: 'ask', form: data }) }).then(function (r) { return r.json(); }).then(function (r) {
      btn.disabled = false;
      if (r && r.ok) { form.reset(); say('잘 받았습니다' + (r.no ? ' (문의번호 ' + r.no + ')' : '') + '. 확인 후 연락드릴게요.', true); if (W.gtag) W.gtag('event', 'generate_lead', { method: 'dlx_ask' }); }
      else say((r && r.msg) || '보내지 못했어요. 잠시 뒤 다시 시도해 주세요.');
    }).catch(function () { btn.disabled = false; say('보내지 못했어요. 전화(010-2390-3811)로 연락 주세요.'); });
  });

  /* 8. 약관 창 */
  var modal = $('#dlModal'), last = null;
  var TITLE = { terms: '서비스 이용약관', privacy: '개인정보처리방침', email: '무단이메일수집거부' };
  function closeModal() { if (modal && !modal.hidden) { modal.hidden = true; D.body.style.overflow = ''; if (last) last.focus(); } }
  D.addEventListener('click', function (e) {
    var b = e.target.closest('[data-dl-policy]');
    if (b && modal) { var t = D.getElementById('dl-policy-' + b.getAttribute('data-dl-policy')); if (!t) return; last = b; $('#dlModalTitle').textContent = TITLE[b.getAttribute('data-dl-policy')] || '안내'; $('#dlModalBody').textContent = t.innerHTML.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>'); modal.hidden = false; D.body.style.overflow = 'hidden'; $('.dl-modal-x', modal).focus(); return; }
    if (modal && (e.target === modal || e.target.closest('[data-dl-close]'))) closeModal();
  });
  W.openModal = function (k) { var b = D.createElement('button'); b.setAttribute('data-dl-policy', k); D.body.appendChild(b); b.click(); b.remove(); };   // 예전 가젯·글의 openModal('terms') 호환

  /* ───── 글 화면 ───── */
  /* 9. 광고 영역: 가젯 → 글 안 제자리 (비었으면 공간 없앰) */
  function isZoneEmpty(src) {
    if (!src) return true;
    var ws = src.querySelectorAll('.widget'), has = false;
    Array.prototype.forEach.call(ws, function (w) { var c = w.querySelector('.widget-content'); if (c && (c.innerText.trim().length > 10 || c.querySelector('iframe, img, ins'))) has = true; });
    if (!ws.length && !src.innerHTML.trim()) return true;
    return !has;
  }
  function moveElement(sid, tid) {
    var s = D.getElementById(sid); if (!s) return;
    var t = D.getElementById(tid);
    if (isZoneEmpty(s) || !t) { s.remove(); return; }
    if (t.contains(s)) return;
    t.appendChild(s); s.style.display = 'block';
  }
  moveElement('Post-Top-Ad-Zone', 'ad-target-below-title');
  moveElement('Post-Bottom-Ad-Zone', 'post-bottom-target');
  moveElement('Below-Nav-Ad-Zone', 'ad-target-below-nextprev');
  var mid = D.getElementById('Post-Middle-Ad-Zone'), body = D.getElementById('post-body');
  if (mid) {
    if (isZoneEmpty(mid) || !body) mid.remove();
    else {
      var hs = body.querySelectorAll('h2, h3'), ps = body.querySelectorAll('p'), done = false;
      if (hs.length >= 3) { hs[2].parentNode.insertBefore(mid, hs[2]); done = true; }
      else if (ps.length >= 8) { var m = Math.floor(ps.length / 2); ps[m].parentNode.insertBefore(mid, ps[m].nextSibling); done = true; }
      if (done) mid.style.display = 'block'; else mid.remove();
    }
  }

  /* 10. 글 안 링크·이미지·단독 링크 버튼 */
  $$('.post-body a').forEach(function (a) { if (a.hostname && a.hostname !== location.hostname && a.href.indexOf('javascript') !== 0) { a.target = '_blank'; a.rel = 'noopener noreferrer'; } });
  $$('.post-body img').forEach(function (img, i) {
    if (/\/s[0-9]+.*?\//.test(img.src)) {
      img.src = img.src.replace(/\/s[0-9]+.*?\//, '/w1200/');
      var p = img.parentElement; if (p && p.tagName === 'A' && /\/s[0-9]+.*?\//.test(p.href)) p.href = p.href.replace(/\/s[0-9]+.*?\//, '/s1600/');
    }
    img.setAttribute('loading', i === 0 ? 'eager' : 'lazy'); img.setAttribute('decoding', 'async');
    if (!img.alt) { var t = $('.post-title'); if (t) img.alt = t.textContent.trim(); }
    img.removeAttribute('width'); img.removeAttribute('height');
  });
  var EXT = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>';
  $$('.post-body').forEach(function (area) {
    $$('a', area).forEach(function (a) {
      if (a.querySelector('img') || a.classList.contains('cargoda-flat-cta')) return;
      if (a.hasAttribute('style') && a.getAttribute('style').trim() !== '') return;
      var blk = a.closest('p, div, li, h2, h3, h4'); if (!blk) return;
      if (blk.classList.contains('post-body')) blk = a.parentElement;
      var bt = blk.textContent.replace(/\s+/g, ''), lt = a.textContent.replace(/\s+/g, '');
      if (bt === lt && lt.length > 0) {
        var wrap = D.createElement('div'); wrap.className = 'cargoda-flat-cta-wrap';
        a.className = 'cargoda-flat-cta'; a.innerHTML = '<span>' + esc(a.textContent.trim()) + '</span>' + EXT;
        if (a.parentElement) { a.parentElement.insertBefore(wrap, a); wrap.appendChild(a); }
      }
    });
  });

  /* 10-1. 날짜 표시를 2026. 02. 17 꼴로 (블로그 날짜 형식 설정과 상관없이) */
  $$('time[datetime]').forEach(function (t) { var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(t.getAttribute('datetime')); if (m) t.textContent = m[1] + '. ' + m[2] + '. ' + m[3]; });

  /* 11. 글 목차 (소제목이 3개 이상인 글) */
  if (body && D.body.classList.contains('dl-post')) {
    var h2 = $$('h2', body).filter(function (h) { return h.textContent.trim(); });
    if (h2.length >= 3) {
      var box = D.createElement('nav'); box.className = 'post-toc'; box.setAttribute('aria-label', '목차');
      box.innerHTML = '<b>목차</b><ol>' + h2.map(function (h, i) { if (!h.id) h.id = 'toc-' + (i + 1); return '<li><a href="#' + h.id + '">' + esc(h.textContent.trim()) + '</a></li>'; }).join('') + '</ol>';
      body.parentNode.insertBefore(box, body);
    }
  }
})();

